關鍵程式包含資料化農事風險評估與 Leaflet 地圖 SSR 隔離：

```typescript
// 數據化風險評估邏輯
export function evaluateAgriRisks(forecast: WeeklyForecastItem[], crop: string) {
  const maxTemp = Math.max(...forecast.map(f => f.temperatureMax));
  if (maxTemp >= 35 && (crop === 'rice' || crop === 'vegetable')) {
    return [{ ruleId: 'RULE-HEAT-01', severity: 'high', userMessage: '極端高溫熱害風險' }];
  }
  return [];
}

// Leaflet Client-only Dynamic Import
const WeatherMapInner = dynamic(() => import('./weather-map-inner'), { ssr: false });
```
